enum Language { JAVA, PYTHON, CPP }
enum Verdict { ACCEPTED, WRONG_ANSWER, TIME_LIMIT_EXCEEDED, MEMORY_LIMIT_EXCEEDED, RUNTIME_ERROR, COMPILE_ERROR, INTERNAL_ERROR, PENDING }
enum SubmissionStatus { QUEUED, COMPILING, RUNNING, COMPLETED }

record Problem(String problemId, String title,
               List<TestCase> testCases,
               int timeLimitMs, int memoryLimitKb) {}

record TestCase(String testCaseId, String input,
                String expectedOutput, boolean isSample, int orderIndex) {}

record TestCaseResult(String testCaseId, Verdict verdict,
                      int runtimeMs, int memoryKb, String actualOutput) {}

record CompileResult(boolean success, String errorMessage, String binaryPath) {
    public static CompileResult success(String binary) {
        return new CompileResult(true, null, binary);
    }
    public static CompileResult failure(String error) {
        return new CompileResult(false, error, null);
    }
}

record ExecutionResult(int exitCode, String stdout, String stderr,
                        int runtimeMs, int memoryKb, boolean timedOut, boolean memExceeded) {}

class Submission {
    private final String submissionId;
    private final String userId;
    private final String problemId;
    private final Language language;
    private final String sourceCode;
    private volatile SubmissionStatus status = SubmissionStatus.QUEUED;
    private final List<TestCaseResult> testCaseResults =
        Collections.synchronizedList(new ArrayList<>());
    private volatile Verdict overallVerdict = Verdict.PENDING;
    private final Instant submittedAt = Instant.now();

    public Submission(String userId, String problemId,
                      Language language, String code) {
        this.submissionId = UUID.randomUUID().toString();
        this.userId = userId;
        this.problemId = problemId;
        this.language = language;
        this.sourceCode = code;
    }

    public void setStatus(SubmissionStatus s)   { this.status = s; }
    public void setOverallVerdict(Verdict v)     { this.overallVerdict = v; }
    public void addTestResult(TestCaseResult r)  { testCaseResults.add(r); }

    public String getSubmissionId()     { return submissionId; }
    public String getUserId()           { return userId; }
    public String getProblemId()        { return problemId; }
    public Language getLanguage()       { return language; }
    public String getSourceCode()       { return sourceCode; }
    public SubmissionStatus getStatus() { return status; }
    public Verdict getOverallVerdict()  { return overallVerdict; }
    public List<TestCaseResult> getTestCaseResults() { return testCaseResults; }
}

interface LanguageExecutor {
    CompileResult compile(String sourceCode, String workDir);
    ExecutionResult execute(String workDir, String input,
                            int timeLimitMs, int memLimitKb);
    Language getLanguage();
}

class JavaExecutor implements LanguageExecutor {
    @Override
    public CompileResult compile(String code, String workDir) {
        try {
            // Write source to Main.java
            Path source = Path.of(workDir, "Main.java");
            Files.writeString(source, code);

            // javac Main.java
            ProcessBuilder pb = new ProcessBuilder("javac", "Main.java")
                .directory(new File(workDir))
                .redirectErrorStream(true);
            Process proc = pb.start();
            String output = new String(proc.getInputStream().readAllBytes());
            int exit = proc.waitFor();

            if (exit != 0) return CompileResult.failure(output);
            return CompileResult.success(workDir + "/Main.class");
        } catch (Exception e) {
            return CompileResult.failure("Compiler crashed: " + e.getMessage());
        }
    }

    @Override
    public ExecutionResult execute(String workDir, String input,
                                    int timeLimitMs, int memLimitKb) {
        try {
            ProcessBuilder pb = new ProcessBuilder(
                    "java", "-Xmx" + memLimitKb + "k", "-cp", workDir, "Main")
                .directory(new File(workDir));
            long startTime = System.currentTimeMillis();
            Process proc = pb.start();

            // Feed input
            proc.getOutputStream().write(input.getBytes());
            proc.getOutputStream().close();

            // Wait with timeout
            boolean finished = proc.waitFor(timeLimitMs, TimeUnit.MILLISECONDS);
            long elapsed = System.currentTimeMillis() - startTime;

            if (!finished) {
                proc.destroyForcibly();
                return new ExecutionResult(-1, "", "TLE",
                    (int) elapsed, 0, true, false);
            }

            String stdout = new String(proc.getInputStream().readAllBytes());
            String stderr = new String(proc.getErrorStream().readAllBytes());
            int exit = proc.exitValue();

            // Memory tracking is OS-level; simplified here
            int memoryUsed = 0; // Would read /proc/pid/status in production

            return new ExecutionResult(exit, stdout, stderr,
                (int) elapsed, memoryUsed, false, false);
        } catch (Exception e) {
            return new ExecutionResult(-1, "", e.getMessage(),
                0, 0, false, false);
        }
    }

    @Override
    public Language getLanguage() { return Language.JAVA; }
}

class PythonExecutor implements LanguageExecutor {
    @Override
    public CompileResult compile(String code, String workDir) {
        try {
            // Python: syntax check only (no separate binary)
            Path source = Path.of(workDir, "solution.py");
            Files.writeString(source, code);

            ProcessBuilder pb = new ProcessBuilder(
                    "python3", "-m", "py_compile", "solution.py")
                .directory(new File(workDir))
                .redirectErrorStream(true);
            Process proc = pb.start();
            String output = new String(proc.getInputStream().readAllBytes());
            int exit = proc.waitFor();

            if (exit != 0) return CompileResult.failure(output);
            return CompileResult.success(workDir + "/solution.py");
        } catch (Exception e) {
            return CompileResult.failure(e.getMessage());
        }
    }

    @Override
    public ExecutionResult execute(String workDir, String input,
                                    int timeLimitMs, int memLimitKb) {
        // Similar to Java but: python3 solution.py
        // ... same pattern, different command
        return new ExecutionResult(0, "", "", 0, 0, false, false); // stub
    }

    @Override
    public Language getLanguage() { return Language.PYTHON; }
}

class JudgeService {

    public Verdict judge(String actual, String expected) {
        String normActual = normalizeOutput(actual);
        String normExpected = normalizeOutput(expected);

        if (normActual.equals(normExpected)) return Verdict.ACCEPTED;
        return Verdict.WRONG_ANSWER;
    }

    // Strip trailing whitespace per line + trailing empty lines
    String normalizeOutput(String output) {
        if (output == null) return "";
        return Arrays.stream(output.split("\n", -1))
            .map(String::stripTrailing)
            .collect(Collectors.joining("\n"))
            .stripTrailing();
    }
}

class SubmissionService {
    private final BlockingQueue<Submission> queue;
    private final ExecutorService workerPool;
    private final ConcurrentHashMap<String, Submission> submissions = new ConcurrentHashMap<>();
    private final Map<String, Problem> problems;
    private final Map<Language, LanguageExecutor> executors;
    private final JudgeService judgeService = new JudgeService();
    private volatile boolean running = true;

    public SubmissionService(int queueSize, int numWorkers,
                              Map<String, Problem> problems,
                              Map<Language, LanguageExecutor> executors) {
        this.queue = new ArrayBlockingQueue<>(queueSize);
        this.problems = problems;
        this.executors = executors;
        this.workerPool = Executors.newFixedThreadPool(numWorkers);
        for (int i = 0; i < numWorkers; i++) {
            workerPool.submit(this::workerLoop);
        }
    }

    // ── Submit ────────────────────────────
    public String submit(String userId, String problemId,
                          Language language, String code) {
        if (!problems.containsKey(problemId))
            throw new ProblemNotFoundException(problemId);
        if (!executors.containsKey(language))
            throw new UnsupportedLanguageException(language.name());

        Submission sub = new Submission(userId, problemId, language, code);
        submissions.put(sub.getSubmissionId(), sub);

        if (!queue.offer(sub)) {
            sub.setStatus(SubmissionStatus.COMPLETED);
            sub.setOverallVerdict(Verdict.INTERNAL_ERROR);
            throw new QueueFullException("Judge queue is full, try again later");
        }
        return sub.getSubmissionId();
    }

    // ── Poll result ──────────────────────
    public Submission getResult(String submissionId) {
        Submission sub = submissions.get(submissionId);
        if (sub == null)
            throw new SubmissionNotFoundException(submissionId);
        return sub;
    }

    // ── Worker loop ──────────────────────
    private void workerLoop() {
        while (running) {
            try {
                Submission sub = queue.poll(1, TimeUnit.SECONDS);
                if (sub == null) continue;
                evaluate(sub);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }
    }

    // ── Evaluation pipeline ──────────────
    private void evaluate(Submission sub) {
        try {
            Problem problem = problems.get(sub.getProblemId());
            LanguageExecutor executor = executors.get(sub.getLanguage());

            // Create isolated work directory
            String workDir = createTempDir(sub.getSubmissionId());

            // Phase 1: Compile
            sub.setStatus(SubmissionStatus.COMPILING);
            CompileResult compileResult = executor.compile(sub.getSourceCode(), workDir);

            if (!compileResult.success()) {
                sub.setOverallVerdict(Verdict.COMPILE_ERROR);
                sub.setStatus(SubmissionStatus.COMPLETED);
                return;
            }

            // Phase 2: Run against each test case
            sub.setStatus(SubmissionStatus.RUNNING);
            Verdict overallVerdict = Verdict.ACCEPTED;

            for (TestCase tc : problem.testCases()) {
                ExecutionResult execResult = executor.execute(
                    workDir, tc.input(),
                    problem.timeLimitMs(), problem.memoryLimitKb());

                Verdict testVerdict;
                if (execResult.timedOut()) {
                    testVerdict = Verdict.TIME_LIMIT_EXCEEDED;
                } else if (execResult.memExceeded()) {
                    testVerdict = Verdict.MEMORY_LIMIT_EXCEEDED;
                } else if (execResult.exitCode() != 0) {
                    testVerdict = Verdict.RUNTIME_ERROR;
                } else {
                    testVerdict = judgeService.judge(
                        execResult.stdout(), tc.expectedOutput());
                }

                sub.addTestResult(new TestCaseResult(
                    tc.testCaseId(), testVerdict,
                    execResult.runtimeMs(), execResult.memoryKb(),
                    testVerdict == Verdict.WRONG_ANSWER ? execResult.stdout() : null));

                // Short-circuit on first failure (optimization)
                if (testVerdict != Verdict.ACCEPTED && overallVerdict == Verdict.ACCEPTED) {
                    overallVerdict = testVerdict;
                    // Continue running remaining tests for full feedback
                    // (or break here for competitive judge — configurable)
                }
            }

            sub.setOverallVerdict(overallVerdict);
            sub.setStatus(SubmissionStatus.COMPLETED);

            // Cleanup temp directory
            cleanupTempDir(workDir);

        } catch (Exception e) {
            sub.setOverallVerdict(Verdict.INTERNAL_ERROR);
            sub.setStatus(SubmissionStatus.COMPLETED);
        }
    }

    private String createTempDir(String subId) {
        try {
            return Files.createTempDirectory("judge-" + subId).toString();
        } catch (IOException e) {
            throw new RuntimeException("Failed to create temp dir", e);
        }
    }

    private void cleanupTempDir(String workDir) {
        try {
            // rm -rf workDir
            Path path = Path.of(workDir);
            Files.walk(path).sorted(Comparator.reverseOrder())
                .map(Path::toFile).forEach(File::delete);
        } catch (IOException ignored) {}
    }

    public void shutdown() {
        running = false;
        workerPool.shutdown();
    }
}
